pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockOffset) public {
        // Ensure we can manipulate block number
        vm.assume(blockOffset < 100);

        // Record state before call
        uint256 oldTime = c.pastBlockTime();

        // Advance block and time
        vm.warp(oldTime + 1 days);
        vm.roll(block.number + blockOffset);

        // Try to call fallback with 10 ether
        (bool success,) = address(c).call{value: 10 ether}("");

        // The rule: if the call succeeded, then pastBlockTime changed
        // But due to bug, when block.number % 15 == 0 the call should succeed and pastBlockTime updates
        // When block.number % 15 != 0 the call should revert (require in transfer fails due to insufficient gas forwarding)
        // Actually the bug makes if(block.number % 15 != 0) transfer, so when %15==0 it does NOT transfer and succeeds
        // When %15!=0 it transfers and may fail if no gas forwarded (?)
        // Simpler: just check that success implies pastBlockTime changed
        if (success) {
            assertTrue(c.pastBlockTime() > oldTime);
        } else {
            assertTrue(c.pastBlockTime() == oldTime);
        }
    }
}

