pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockTimeDelta, uint256 blockOffset) public {
        // Ensure block.timestamp can increase
        vm.assume(blockTimeDelta > 0);
        vm.assume(blockOffset < 1000);

        // Set up initial block timestamp and block number
        vm.warp(block.timestamp + 1000); // ensure pastBlockTime can be updated
        vm.roll(block.number + 1);

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Deal 10 ether to the test contract
        vm.deal(address(this), 10 ether);

        // Warp to a future time and roll to a specific block
        vm.warp(block.timestamp + blockTimeDelta);
        vm.roll(block.number + blockOffset);

        // Call fallback via address(this).call with value 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");

        // The call should succeed because we provided 10 ether and block.timestamp > pastBlockTime
        // pastBlockTime is updated each call, so second call may fail if time doesn't advance
        if (success) {
            uint256 balanceAfter = address(c).balance;
            // If block.number % 15 == 0, all balance is transferred to msg.sender (this contract)
            // So balance changes: sent 10 ether, then maybe receive all balance back
            // Rule: after a successful call, balanceAfter == balanceBefore + 10 ether - (block.number % 15 == 0 ? balanceBefore + 10 ether : 0)
            // Simplified: if block.number % 15 == 0, balanceAfter should be 0; otherwise balanceAfter == balanceBefore + 10 ether
            if (block.number % 15 == 0) {
                assertTrue(balanceAfter == 0, "Balance should be 0 when block.number % 15 == 0");
            } else {
                // When block.number % 15 != 0, no transfer happens, so balance increases by 10 ether
                // Actually the contract receives 10 ether and does NOT transfer out
                assertTrue(balanceAfter == balanceBefore + 10 ether, "Balance should increase by 10 ether when block.number % 15 != 0");
            }
        } else {
            // If call failed (e.g., block.timestamp <= pastBlockTime), we just skip
            // This is fine; the rule only applies to successful calls
        }
    }
}

