pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { 
        c = new C(); 
    }

    function testFuzz_property(uint256 blockNumber, uint256 pastBlockTime, uint256 timestamp) public {
        // Constrain inputs to satisfy the requires in fallback
        vm.assume(timestamp > pastBlockTime);
        // Set the block number and timestamp
        vm.roll(blockNumber);
        vm.warp(timestamp);

        // Set pastBlockTime so that the second require can pass (timestamp > pastBlockTime)
        // We'll call fallback directly with the right value
        uint256 balanceBefore = address(c).balance;

        // Send 10 ether to trigger fallback
        (bool success, ) = address(c).call{value: 10 ether}("");

        uint256 balanceAfter = address(c).balance;

        // The rule: balance decreases iff block.number % 15 == 0
        // Note: the fallback only transfers when block.number % 15 != 0 in the mutant
        assertTrue(success == true); // The call should succeed given our assumptions

        bool balanceDecreased = (balanceBefore > balanceAfter);
        bool blockMod15Zero = (blockNumber % 15 == 0);

        assertTrue(balanceDecreased == blockMod15Zero);
    }
}

