pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 timestamp) public {
        // Ensure timestamp is in the past for the first call
        vm.assume(timestamp < block.timestamp);
        vm.deal(address(this), value);

        // Try to call the fallback with msg.value = 0 (mutant) or 10 ether (reference)
        // We'll just call it with the given value — if it reverts, that's fine.
        (bool success, ) = address(c).call{value: value}("");
        // Rule: after any call, the contract should have zero balance unless 10 ether was sent and block number % 15 == 0
        // For the mutant, msg.value == 0 always, so the first require passes, and the second require may pass if timestamp > pastBlockTime.
        // In that case, pastBlockTime updates, and if block.number % 15 == 0, it sends all balance to msg.sender => balance becomes 0.
        // If block.number % 15 != 0, the balance stays as it was (which is 0 initially and remains 0 because no ether was ever locked).
        // For the reference, sending 10 ether would increase balance, but the mutant always rejects values != 0.
        // So the general rule: c's balance is always 0 after any call (since mutant always requires msg.value == 0 ether).
        assertTrue(address(c).balance == 0);
    }
}

