pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // Restrict amount to be exactly 10 ether (the reference requires that for state change)
        vm.assume(amount == 10 ether);

        uint256 prevPastBlockTime = c.pastBlockTime();

        // Call fallback with the specified amount
        (bool success, ) = address(c).call{value: amount}("");

        // The rule: after a call that sends exactly 10 ether (and satisfies the timestamp condition),
        // pastBlockTime must have changed (because the reference updates it).
        // However, the buggy version accepts 0 ether, so if amount=10 ether but buggy accepts only 0 ether,
        // the buggy version will revert (since it requires msg.value == 0) and pastBlockTime stays unchanged.
        // So the assertion: if the call succeeded, then pastBlockTime changed.
        if (success) {
            assertTrue(c.pastBlockTime() != prevPastBlockTime);
        }
    }
}

