        // First call
        vm.deal(address(this), 10 ether);
        vm.prank(address(this));
        vm.warp(timestamp1);
        (bool ok1,) = address(c).call{value: 10 ether}("");

        // Second call
        vm.prank(address(this));
        vm.warp(timestamp2);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // If both succeed, pastBlockTime must have increased
        if (ok1 && ok2) {
            uint256 past1 = c.pastBlockTime();
            // After second call, pastBlockTime is timestamp2
            assertTrue(past1 < timestamp2);
        } else {
            assertTrue(true);
        }
    }
}

