        // Ensure block.number % 15 != 0 so the transfer does NOT occur in reference
        vm.assume(block.number % 15 != 0);
        // Ensure the target block does not overflow
        uint256 targetBlock = block.number + (blockOffset % 100);
        vm.roll(targetBlock);
        // Ensure block.timestamp > pastBlockTime (initially 0)
