        // Fund the contract with 10 ETH so it can pay back
        vm.deal(address(c), 10 ether);
        // Perform the fallback call with 10 ETH
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "fallback reverted");
        // Assert that the contract still holds its initial 10 ETH (balance > 0)
        assertTrue(address(c).balance > 0);
    }
}

