pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        uint initBalance = address(c).balance;
        uint initPastBlockTime = c.pastBlockTime();
        vm.assume(seed % 2 == 0); // To have some control, though the rule works without it
        vm.deal(address(this), 10 ether);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        uint newPast = c.pastBlockTime();
        assertTrue(newPast > initPastBlockTime);
        uint newBalance = address(c).balance;
        // After one fallback, the correct contract may or may not transfer all balance
        // The rule: balance is either 0 (if block % 15 == 0) or >= 10 ether (otherwise)
        assertTrue(newBalance == 0 || newBalance >= 10 ether);
    }
}
